/**
 * Add event listener into Document related to toolbar actions.

 * @param eventName - DOM Event name EG: keydown, wheel, etc.
 * @param callback - behavior that will be executed in the defined event
 * @param callbackCondition - callback condition
 * @param eventCondition - event condition
 * @param element - the element where the event occurs
 */
export declare function useToolbarEvent<T extends Event>(eventName: string, callback: () => void, callbackCondition: (event: T) => boolean, eventCondition: boolean | undefined, element?: HTMLDivElement): void;
